from typing import Annotated

def basic_calculator(
    operation: Annotated[str, "One of add, subtract, multiply, divide"],
    num1: Annotated[float, "First finite numeric operand; booleans rejected"],
    num2: Annotated[float, "Second finite numeric operand; booleans rejected"],
) -> Annotated[float, "Finite arithmetic result"]:
    """
    Performs basic arithmetic operations on two numbers.

    Args:
        operation: The arithmetic operation to perform ('add', 'subtract', 'multiply', 'divide')
        num1: First number (float)
        num2: Second number (float)

    Returns:
        Result of the arithmetic operation as float

    Raises:
        ValueError: For invalid operations, non-numeric inputs, or division by zero
    """
    # Validate operation
    valid_operations = {'add', 'subtract', 'multiply', 'divide'}
    if operation not in valid_operations:
        raise ValueError(f"Invalid operation '{operation}'. Must be one of {valid_operations}.")

    # Validate numeric inputs
    def is_valid_numeric(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and not isinstance(value, complex) and value != float('inf') and value != float('-inf') and not float('nan') == value

    if not is_valid_numeric(num1):
        raise ValueError(f"Invalid first operand '{num1}'. Must be a finite numeric value.")

    if not is_valid_numeric(num2):
        raise ValueError(f"Invalid second operand '{num2}'. Must be a finite numeric value.")

    # Perform operation
    if operation == 'add':
        result = num1 + num2
    elif operation == 'subtract':
        result = num1 - num2
    elif operation == 'multiply':
        result = num1 * num2
    elif operation == 'divide':
        if num2 == 0:
            raise ValueError("Division by zero is not allowed.")
        result = num1 / num2

    # Validate result is finite
    if not isinstance(result, (int, float)) or result == float('inf') or result == float('-inf') or float('nan') == result:
        raise ValueError("Operation resulted in a non-finite value.")

    return float(result)
